-- [1] CSV:pha HUD PHAs all rows key columns
SELECT PARTICIPANT_CODE, FORMAL_PARTICIPANT_NAME, STD_STATE, STATE_FIPS, COUNTY_FIPS, CURRENT_COUNTY_FIPS, COUNTY_NAME, PLACE_FIPS, HA_PROGRAM_TYPE, TOTAL_UNITS, TOTAL_DWELLING_UNITS, ACC_UNITS, SECTION8_UNITS_COUNT, PUBLIC_HOUSING_OCCUPIED, SECTION8_OCCUPIED, REGULAR_VACANT, OPERATING_FUND_AMOUNT, OPERATING_FUND_AMOUNT_PREV_YR, CAPITAL_FUND_AMOUNT, ANNUAL_EXPENSE_AMOUNT, SPENDING_PER_MONTH, PHAS_DESIGNATION, PCT_OCCUPIED, MEDIAN_INCOME_AMOUNT, LAST_UPDATED_AT FROM LIBRARY_MARTS.HOUSING.HOUSING__FED_HUD_PUBLIC_HOUSING_AUTHORITIES;

-- [2] CSV:fjc3 FJC judges state and nomination dates
SELECT NID, JID, LAST_NAME, FIRST_NAME, BIRTH_STATE, DEATH_STATE, BIRTH_YEAR, GENDER, RACE_OR_ETHNICITY, COURT_TYPE_1, COURT_NAME_1, APPOINTING_PRESIDENT_1, PARTY_OF_APPOINTING_PRESIDENT_1, ABA_RATING_1, RECESS_APPOINTMENT_DATE_1, NOMINATION_DATE_1, COMMITTEE_REFERRAL_DATE_1, HEARING_DATE_1, JUDICIARY_COMMITTEE_ACTION_1, COMMITTEE_ACTION_DATE_1, SENATE_VOTE_TYPE_1, AYES_NAYS_1, CONFIRMATION_DATE_1, COMMISSION_DATE_1, SERVICE_AS_CHIEF_JUDGE_BEGIN_1, SENIOR_STATUS_DATE_1, TERMINATION_1, TERMINATION_DATE_1, C_2_ND_SERVICE_AS_CHIEF_JUDGE_BEGIN_2, SERVICE_AS_CHIEF_JUDGE_BEGIN_2, COURT_NAME_2 FROM LIBRARY_MARTS.JUSTICE.JUSTICE__FED_FJC_ARTICLE_III_JUDGES;

-- [3] HUDOC first look
SELECT COUNTRY, PERSON_NAME, JUDGMENT_DATE, LANGUAGE, DOC_TYPE, IMPORTANCE, RESPONDENT, VIOLATION, JUDGMENT_YEAR, APPNO, CASE_ID FROM LIBRARY_MARTS.JUSTICE.JUSTICE__INTL_HUDOC LIMIT 5;

-- [4] FRA equip first look
SELECT INCIDENT_KEY, REPORT_KEY, DATE, YEAR, STATE_ABBREVIATION, STATE_CODE, COUNTY_CODE, REPORTING_RAILROAD_NAME, REPORTING_PARENT_RAILROAD_NAME, OTHER_RAILROAD_NAME, EQUIPMENT_DAMAGE_COST, TRACK_DAMAGE_COST, TOTAL_DAMAGE_COST, TOTAL_PERSONS_KILLED, HAZMAT_RELEASED_CARS FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_EQUIPMENT_ACCIDENTS LIMIT 5;

-- [5] ECHO first look
SELECT FRS_ID, FACILITY_NAME, STATE, FIPS_CODE, TOTAL_PENALTIES, PENALTY_COUNT, FORMAL_ACTION_COUNT, IS_ACTIVE, IS_FEDERAL_FACILITY, DATE_LAST_PENALTY FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO LIMIT 5;

-- [6] PPP first look
SELECT BORROWER_NAME, BORROWER_CITY, BORROWER_STATE, BORROWER_ZIP, DATE_APPROVED, CURRENT_APPROVAL_AMOUNT, SERVICING_LENDER_NAME, NAICS_CODE, JOBS_REPORTED, LOAN_STATUS FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_SBA_PPP LIMIT 5;

-- [7] FRA casualties first look
SELECT RAILROAD_CODE, RAILROAD_NAME, REPORTING_PARENT_RAILROAD_NAME, REPORTING_RAILROAD_HOLDING_COMPANY, INCIDENT_KEY, DATE, STATE_NAME, TYPE_OF_PERSON, FATALITY FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_CASUALTIES LIMIT 5;

-- [8] OSHA 2023 first look
SELECT ESTABLISHMENT_ID, ESTABLISHMENT_NAME, EIN, COMPANY_NAME, STATE, NAICS_CODE, DATE_OF_INCIDENT, INCIDENT_OUTCOME, DATE_OF_DEATH, YEAR_FILING_FOR FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2023 LIMIT 5;

-- [9] FQHC first look
SELECT NPI, LAST_NAME, FIRST_NAME, SITE_NAME, HEALTH_CENTER_NAME, SITE_STATE, EXCLUSION_DATE, EXCLUSION_TYPE, IS_EXCLUDED, OPTOUT_EFFECTIVE_DATE, IS_OPTED_OUT, NPI_DEACTIVATION_DATE, MATCH_NOTE FROM LIBRARY_MARTS.HEALTH.HEALTH__FQHC_SITE_PEOPLE LIMIT 5;

-- [10] CSV:hudoc HUDOC by country, doc type, language, year
SELECT COUNTRY, RESPONDENT, DOC_TYPE, LANGUAGE, JUDGMENT_YEAR, COUNT(*) n, COUNT(DISTINCT CASE_ID) cases, COUNT(DISTINCT APPNO) appnos, SUM(IFF(NULLIF(TRIM(VIOLATION),'') IS NOT NULL,1,0)) viol, SUM(IFF(NULLIF(TRIM(NONVIOLATION),'') IS NOT NULL,1,0)) nonviol, SUM(IFF(NULLIF(TRIM(JUDGMENT_DATE::varchar),'') IS NULL,1,0)) nodate, MIN(IMPORTANCE) imp_min, MAX(IMPORTANCE) imp_max, SUM(IFF(IMPORTANCE::varchar IN ('1','KEY','Key'),1,0)) imp1 FROM LIBRARY_MARTS.JUSTICE.JUSTICE__INTL_HUDOC GROUP BY 1,2,3,4,5;

-- [11] CSV:fraeq FRA equipment accidents deduped on INCIDENT_KEY, state x year
WITH i AS (SELECT INCIDENT_KEY, MAX(STATE_ABBREVIATION) st, MAX(YEAR) yr, MAX(TRY_TO_NUMBER(TOTAL_DAMAGE_COST::varchar)) dmg, MAX(TRY_TO_NUMBER(EQUIPMENT_DAMAGE_COST::varchar)) eqdmg, MAX(TRY_TO_NUMBER(TOTAL_PERSONS_KILLED::varchar)) killed, MAX(TRY_TO_NUMBER(HAZMAT_RELEASED_CARS::varchar)) hzrel, MAX(TRY_TO_NUMBER(PERSONS_EVACUATED::varchar)) evac, COUNT(*) rws, MAX(ACCIDENT_TYPE) atype FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_EQUIPMENT_ACCIDENTS GROUP BY 1)
SELECT st, yr, COUNT(*) incidents, SUM(rws) rws, SUM(dmg) dmg, SUM(eqdmg) eqdmg, SUM(killed) killed, SUM(IFF(hzrel>0,1,0)) hz_inc, SUM(evac) evac, SUM(IFF(atype ILIKE '%derail%',1,0)) derail, MAX(dmg) maxdmg, MAX_BY(INCIDENT_KEY, dmg) maxkey FROM i GROUP BY 1,2;

-- [12] CSV:echo EPA ECHO county roll-up
SELECT LPAD(FIPS_CODE::varchar,5,'0') fips, COUNT(*) fac, SUM(IFF(IS_ACTIVE::varchar ILIKE 'true',1,0)) active, SUM(TRY_TO_NUMBER(TOTAL_PENALTIES::varchar)) pen, SUM(IFF(TRY_TO_NUMBER(TOTAL_PENALTIES::varchar)>0,1,0)) fac_pen, SUM(TRY_TO_NUMBER(PENALTY_COUNT::varchar)) pen_n, SUM(TRY_TO_NUMBER(FORMAL_ACTION_COUNT::varchar)) formal, SUM(IFF(IS_FEDERAL_FACILITY::varchar ILIKE 'true',TRY_TO_NUMBER(TOTAL_PENALTIES::varchar),0)) fed_pen, MAX(TRY_TO_NUMBER(TOTAL_PENALTIES::varchar)) maxpen, MAX_BY(FACILITY_NAME, TRY_TO_NUMBER(TOTAL_PENALTIES::varchar)) topfac FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO GROUP BY 1;

-- [13] ECHO penalty column profile
SELECT COUNT(*) n, COUNT(TOTAL_PENALTIES) nn, SUM(IFF(TOTAL_PENALTIES>0,1,0)) pos, MEDIAN(IFF(TOTAL_PENALTIES>0,TOTAL_PENALTIES,NULL)) med, MAX(TOTAL_PENALTIES) mx, COUNT(DISTINCT FIPS_CODE) fips, SUM(IFF(FIPS_CODE IS NULL OR TRIM(FIPS_CODE::varchar)='',1,0)) nofips, MIN(DATE_LAST_PENALTY) d1, MAX(DATE_LAST_PENALTY) d2, COUNT(PENALTY_COUNT) pc_nn FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO;

-- [14] ECHO top 15 penalties
SELECT FRS_ID, FACILITY_NAME, STATE, FIPS_CODE, TOTAL_PENALTIES, PENALTY_COUNT, LAST_PENALTY_AMT, LAST_PENALTY_SHARED_FACILITY_N, IS_FEDERAL_FACILITY, DATE_LAST_PENALTY FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO ORDER BY TOTAL_PENALTIES DESC NULLS LAST LIMIT 15;

-- [15] HUDOC top 20 repeated names in English judgments
SELECT PERSON_NAME, COUNT(*) n, COUNT(DISTINCT APPNO) appnos, COUNT(DISTINCT COUNTRY) countries, MAX(COUNTRY) country, SUM(IFF(NULLIF(TRIM(VIOLATION),'') IS NOT NULL,1,0)) viol FROM LIBRARY_MARTS.JUSTICE.JUSTICE__INTL_HUDOC WHERE DOC_TYPE='HEJUD' GROUP BY 1 ORDER BY n DESC LIMIT 20;

-- [16] CSV:hudsan HUDOC person names (2+ words) matched to OpenSanctions names
WITH h AS (SELECT DISTINCT TRIM(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(PERSON_NAME),'^CASE OF ',''),' (AND OTHERS|V\. .*)$','')) nm, COUNTRY FROM LIBRARY_MARTS.JUSTICE.JUSTICE__INTL_HUDOC WHERE LANGUAGE='ENG' AND DOC_TYPE IN ('HEJUD','HEDEC','HECOM')),
h2 AS (SELECT nm, LISTAGG(DISTINCT COUNTRY,';') ctry FROM h WHERE nm LIKE '% %' AND nm NOT LIKE '%,%' AND nm NOT LIKE '% AND %' AND LENGTH(nm)>=8 GROUP BY nm),
o AS (SELECT UPPER(TRIM(NAME)) nm, MAX(COUNTRIES) oc, MAX(ENTITY_TYPE) et, MAX(LEFT(DATASETS,120)) ds, COUNT(*) on_n FROM LIBRARY_MARTS.JUSTICE.JUSTICE__INTL_OPENSANCTIONS_DEFAULT WHERE NAME LIKE '% %' GROUP BY 1)
SELECT h2.nm, h2.ctry, o.oc, o.et, o.ds, o.on_n, (SELECT COUNT(*) FROM h2) h_names FROM h2 JOIN o ON o.nm=h2.nm;

-- [17] FRA equip top 20 reporting railroads and code/name bridge to casualties
WITH e AS (SELECT REPORTING_RAILROAD_CODE cd, UPPER(TRIM(REPORTING_RAILROAD_NAME)) nm, COUNT(DISTINCT INCIDENT_KEY) inc, SUM(TRY_TO_NUMBER(TOTAL_PERSONS_KILLED::varchar)) killed FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_EQUIPMENT_ACCIDENTS GROUP BY 1,2),
c AS (SELECT UPPER(TRIM(RAILROAD_NAME)) nm, MAX(RAILROAD_CODE) cd, COUNT(DISTINCT RAILROAD_CODE) ncd, COUNT(*) n FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_CASUALTIES GROUP BY 1),
top AS (SELECT cd, nm, inc, killed, 'top' k FROM e ORDER BY inc DESC LIMIT 20)
SELECT k, cd, nm, inc, killed, NULL a, NULL b, NULL c2 FROM top
UNION ALL SELECT 'bridge', NULL, NULL, COUNT(*), SUM(inc), SUM(IFF(c.nm IS NOT NULL,1,0)), SUM(IFF(c.nm IS NOT NULL AND c.cd=e.cd,1,0)), SUM(IFF(c.nm IS NOT NULL,e.inc,0)) FROM e LEFT JOIN c ON c.nm=e.nm;

-- [18] FRA casualties top 20 railroads
SELECT RAILROAD_NAME, MAX(RAILROAD_CODE) cd, COUNT(*) n, SUM(IFF(FATALITY ILIKE 'y%',1,0)) deaths, MIN(DATE) d1, MAX(DATE) d2, MAX(REPORTING_PARENT_RAILROAD_NAME) parent FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_CASUALTIES GROUP BY 1 ORDER BY n DESC LIMIT 20;

-- [19] FRA casualties railroad names bridged to PPP borrowers
WITH c AS (SELECT TRIM(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RAILROAD_NAME),'[^A-Z0-9 ]',' '),'\s+',' ')) nm, MODE(STATE_NAME) st, COUNT(*) n FROM LIBRARY_MARTS.TRANSPORT.TRANSPORT__FED_FRA_CASUALTIES GROUP BY 1),
p AS (SELECT TRIM(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(BORROWER_NAME),'[^A-Z0-9 ]',' '),'\s+',' ')) nm, BORROWER_STATE st, SUM(CURRENT_APPROVAL_AMOUNT) amt, MIN(DATE_APPROVED) d FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_SBA_PPP GROUP BY 1,2)
SELECT c.nm, c.st, c.n, p.st pst, p.amt, p.d, (SELECT COUNT(*) FROM c WHERE nm LIKE '% %') c_names FROM c JOIN p ON p.nm=c.nm WHERE c.nm LIKE '% %' ORDER BY c.n DESC LIMIT 60;

-- [20] PPP top 20 repeated borrower names
SELECT BORROWER_NAME, COUNT(*) n, COUNT(DISTINCT BORROWER_STATE) sts, COUNT(DISTINCT BORROWER_ZIP) zips, SUM(CURRENT_APPROVAL_AMOUNT) amt, MAX(BORROWER_STATE) st FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_SBA_PPP GROUP BY 1 ORDER BY n DESC LIMIT 20;

-- [21] PPP top repeated addresses-by-ZIP9 plus lenders
SELECT 'lender' k, SERVICING_LENDER_NAME v, COUNT(*) n, SUM(CURRENT_APPROVAL_AMOUNT) amt FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_SBA_PPP GROUP BY 2 QUALIFY ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC)<=10;

-- [22] PPP name+state bridge to IRS EO BMF, city agreement
WITH p AS (SELECT TRIM(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(BORROWER_NAME),'[^A-Z0-9 ]',' '),'\b(INC|LLC|CORP|CORPORATION|CO|LTD|THE|INCORPORATED)\b',''),'\s+',' ')) nm, BORROWER_STATE st, MAX(UPPER(TRIM(BORROWER_CITY))) city, MAX(NAICS_CODE) naics, COUNT(*) n, SUM(CURRENT_APPROVAL_AMOUNT) amt FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_SBA_PPP GROUP BY 1,2),
b AS (SELECT TRIM(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(ORG_NAME),'[^A-Z0-9 ]',' '),'\b(INC|LLC|CORP|CORPORATION|CO|LTD|THE|INCORPORATED)\b',''),'\s+',' ')) nm, STATE st, MAX(UPPER(TRIM(CITY))) city, COUNT(DISTINCT EIN) eins FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__FED_IRS_EO_BMF GROUP BY 1,2)
SELECT COUNT(*) p_keys, SUM(IFF(p.nm LIKE '% %',1,0)) p_multi, SUM(IFF(b.nm IS NOT NULL AND p.nm LIKE '% %',1,0)) hit, SUM(IFF(b.nm IS NOT NULL AND p.nm LIKE '% %' AND b.city=p.city,1,0)) city_agree, SUM(IFF(b.nm IS NOT NULL AND p.nm LIKE '% %' AND b.eins=1,1,0)) one_ein, SUM(IFF(LEFT(p.naics::varchar,3)='813',1,0)) naics813, SUM(IFF(LEFT(p.naics::varchar,3)='813' AND b.nm IS NOT NULL,1,0)) hit813, SUM(IFF(b.nm IS NOT NULL AND p.nm LIKE '% %',p.amt,0)) hit_amt, SUM(p.amt) amt FROM p LEFT JOIN b ON b.nm=p.nm AND b.st=p.st;

-- [23] CSV:oshamo OSHA ITA case detail 2023-25: cases and deaths by file and incident month
SELECT f, LEFT(DATE_OF_INCIDENT::varchar,7) mo, COUNT(*) n, SUM(IFF(INCIDENT_OUTCOME::varchar='1',1,0)) deaths FROM (
 SELECT '2023' f, DATE_OF_INCIDENT, INCIDENT_OUTCOME FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2023
 UNION ALL SELECT '2024', DATE_OF_INCIDENT, INCIDENT_OUTCOME FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2024
 UNION ALL SELECT '2025', DATE_OF_INCIDENT, INCIDENT_OUTCOME FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2025) GROUP BY 1,2;

-- [24] CSV:oshaein OSHA ITA per file per EIN: cases, deaths, establishments, name
SELECT f, ein, COUNT(*) n, SUM(IFF(o='1',1,0)) deaths, COUNT(DISTINCT est) ests, MAX(co) co, MAX(st) st, MAX(naics) naics, MIN(dt) d1, MAX(IFF(o='1',dt,NULL)) last_death FROM (
 SELECT '2023' f, REGEXP_REPLACE(EIN::varchar,'[^0-9]','') ein, INCIDENT_OUTCOME::varchar o, ESTABLISHMENT_ID est, COMPANY_NAME co, STATE st, NAICS_CODE naics, DATE_OF_INCIDENT dt FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2023
 UNION ALL SELECT '2024', REGEXP_REPLACE(EIN::varchar,'[^0-9]',''), INCIDENT_OUTCOME::varchar, ESTABLISHMENT_ID, COMPANY_NAME, STATE, NAICS_CODE, DATE_OF_INCIDENT FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2024
 UNION ALL SELECT '2025', REGEXP_REPLACE(EIN::varchar,'[^0-9]',''), INCIDENT_OUTCOME::varchar, ESTABLISHMENT_ID, COMPANY_NAME, STATE, NAICS_CODE, DATE_OF_INCIDENT FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2025) GROUP BY 1,2;

-- [25] CSV:fqhc FQHC site people: excluded or opted-out rows, plus exclusion-year counts
SELECT NPI, LAST_NAME, FIRST_NAME, CREDENTIAL, SITE_NAME, HEALTH_CENTER_NAME, SITE_STATE, EXCLUSION_DATE, EXCLUSION_TYPE, IS_EXCLUDED, OPTOUT_EFFECTIVE_DATE, OPTOUT_END_DATE, IS_OPTED_OUT, NPI_DEACTIVATION_DATE, NPPES_LAST_UPDATE_DATE, LEIE_SPECIALTY, PEOPLE_AT_SITE FROM LIBRARY_MARTS.HEALTH.HEALTH__FQHC_SITE_PEOPLE WHERE NULLIF(TRIM(EXCLUSION_DATE::varchar),'') IS NOT NULL OR IS_EXCLUDED::varchar ILIKE 'true' OR NULLIF(TRIM(OPTOUT_EFFECTIVE_DATE::varchar),'') IS NOT NULL;

-- [26] FQHC profile
SELECT COUNT(*) n, COUNT(DISTINCT NPI) npis, COUNT(DISTINCT BPHC_ASSIGNED_NUMBER) sites, SUM(IFF(IS_EXCLUDED::varchar ILIKE 'true',1,0)) excl, SUM(IFF(IS_OPTED_OUT::varchar ILIKE 'true',1,0)) optout, SUM(IFF(NULLIF(TRIM(NPI_DEACTIVATION_DATE::varchar),'') IS NOT NULL,1,0)) deact, SUM(IFF(IS_HIGH_DENSITY_CAMPUS::varchar ILIKE 'true',1,0)) campus, MAX(PEOPLE_AT_SITE) maxppl FROM LIBRARY_MARTS.HEALTH.HEALTH__FQHC_SITE_PEOPLE;

-- [27] CSV:fqhcpart Excluded FQHC-address NPIs: Open Payments 2022-24 and Part D rows per NPI and year
SELECT 'OP' src, NPI::varchar npi, PROGRAM_YEAR::varchar yr, COUNT(*) n, SUM(TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS) amt, MIN(DATE_OF_PAYMENT) d1, MAX(DATE_OF_PAYMENT) d2 FROM (SELECT NPI, PROGRAM_YEAR, TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS, DATE_OF_PAYMENT FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_OPEN_PAYMENTS WHERE NPI::varchar IN ('1043481138','1174693949','1861715427','1972559227','1871610832','1740206358','1306875604','1629256540','1376727644','1831250489','1184663445','1245230028','1376655845','1902057854','1528111341','1043361546','1740205137','1992717250','1922022623','1174559108','1639122930','1427075175','1841381597','1215901517','1073723433','1841493582','1033251418','1538164942','1568664514','1801839063','1821269481','1215437512','1144399056','1720189087','1093750804','1578727418','1457367351','1841764123','1174621700','1053301671','1851518617','1235142894','1811969074','1629444922','1326037771','1053583104','1689853020','1881649374','1831547868','1962474569','1033301106','1427000819','1912931064','1104008465','1225067044','1184891582','1962594895','1699000224','1881654705','1821022955','1255306767','1598838963','1497147318','1649526765','1386831253','1174714687','1649206376','1376631663','1518296839','1528390358','1659620391','1043272974','1962450254','1609849306','1780183517','1518176601','1538364096','1376513184','1548798309','1659720241','1205175841','1578070298','1699335174','1366623738','1760659460','1003966763','1629158514','1871596643') UNION ALL SELECT NPI, PROGRAM_YEAR, TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS, DATE_OF_PAYMENT FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_OPEN_PAYMENTS_2023 WHERE NPI::varchar IN ('1043481138','1174693949','1861715427','1972559227','1871610832','1740206358','1306875604','1629256540','1376727644','1831250489','1184663445','1245230028','1376655845','1902057854','1528111341','1043361546','1740205137','1992717250','1922022623','1174559108','1639122930','1427075175','1841381597','1215901517','1073723433','1841493582','1033251418','1538164942','1568664514','1801839063','1821269481','1215437512','1144399056','1720189087','1093750804','1578727418','1457367351','1841764123','1174621700','1053301671','1851518617','1235142894','1811969074','1629444922','1326037771','1053583104','1689853020','1881649374','1831547868','1962474569','1033301106','1427000819','1912931064','1104008465','1225067044','1184891582','1962594895','1699000224','1881654705','1821022955','1255306767','1598838963','1497147318','1649526765','1386831253','1174714687','1649206376','1376631663','1518296839','1528390358','1659620391','1043272974','1962450254','1609849306','1780183517','1518176601','1538364096','1376513184','1548798309','1659720241','1205175841','1578070298','1699335174','1366623738','1760659460','1003966763','1629158514','1871596643') UNION ALL SELECT NPI, PROGRAM_YEAR, TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS, DATE_OF_PAYMENT FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_OPEN_PAYMENTS_2022 WHERE NPI::varchar IN ('1043481138','1174693949','1861715427','1972559227','1871610832','1740206358','1306875604','1629256540','1376727644','1831250489','1184663445','1245230028','1376655845','1902057854','1528111341','1043361546','1740205137','1992717250','1922022623','1174559108','1639122930','1427075175','1841381597','1215901517','1073723433','1841493582','1033251418','1538164942','1568664514','1801839063','1821269481','1215437512','1144399056','1720189087','1093750804','1578727418','1457367351','1841764123','1174621700','1053301671','1851518617','1235142894','1811969074','1629444922','1326037771','1053583104','1689853020','1881649374','1831547868','1962474569','1033301106','1427000819','1912931064','1104008465','1225067044','1184891582','1962594895','1699000224','1881654705','1821022955','1255306767','1598838963','1497147318','1649526765','1386831253','1174714687','1649206376','1376631663','1518296839','1528390358','1659620391','1043272974','1962450254','1609849306','1780183517','1518176601','1538364096','1376513184','1548798309','1659720241','1205175841','1578070298','1699335174','1366623738','1760659460','1003966763','1629158514','1871596643')) GROUP BY 1,2,3
UNION ALL SELECT 'PARTD', NPI::varchar, DATA_YEAR::varchar, COUNT(*), SUM(TOTAL_DRUG_COST), NULL, NULL FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_PARTD_PRESCRIBERS WHERE NPI::varchar IN ('1043481138','1174693949','1861715427','1972559227','1871610832','1740206358','1306875604','1629256540','1376727644','1831250489','1184663445','1245230028','1376655845','1902057854','1528111341','1043361546','1740205137','1992717250','1922022623','1174559108','1639122930','1427075175','1841381597','1215901517','1073723433','1841493582','1033251418','1538164942','1568664514','1801839063','1821269481','1215437512','1144399056','1720189087','1093750804','1578727418','1457367351','1841764123','1174621700','1053301671','1851518617','1235142894','1811969074','1629444922','1326037771','1053583104','1689853020','1881649374','1831547868','1962474569','1033301106','1427000819','1912931064','1104008465','1225067044','1184891582','1962594895','1699000224','1881654705','1821022955','1255306767','1598838963','1497147318','1649526765','1386831253','1174714687','1649206376','1376631663','1518296839','1528390358','1659620391','1043272974','1962450254','1609849306','1780183517','1518176601','1538364096','1376513184','1548798309','1659720241','1205175841','1578070298','1699335174','1366623738','1760659460','1003966763','1629158514','1871596643') GROUP BY 1,2,3;

-- [28] CSV:r2names R2 names: recipient name x UEI and officer-1 name x UEI, rolled up
WITH g AS (SELECT RECIPIENT_NAME rn, HIGHLY_COMPENSATED_OFFICER_1_NAME ofc, RECIPIENT_UEI u, COUNT(*) n, SUM(FEDERAL_ACTION_OBLIGATION) amt, GROUPING(RECIPIENT_NAME) g_rn, GROUPING(HIGHLY_COMPENSATED_OFFICER_1_NAME) g_of FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 GROUP BY GROUPING SETS ((RECIPIENT_NAME, RECIPIENT_UEI),(HIGHLY_COMPENSATED_OFFICER_1_NAME, RECIPIENT_UEI),(RECIPIENT_UEI))),
rn AS (SELECT 'name' k, rn v, SUM(n) n, SUM(amt) amt, COUNT(DISTINCT u) ueis, MAX(n)/SUM(n) top_uei_share FROM g WHERE g_rn=0 AND g_of=1 GROUP BY rn QUALIFY ROW_NUMBER() OVER (ORDER BY SUM(n) DESC)<=25),
ofc AS (SELECT 'officer' k, ofc v, SUM(n) n, SUM(amt) amt, COUNT(DISTINCT u) ueis, MAX(n)/SUM(n) FROM g WHERE g_of=0 AND g_rn=1 AND NULLIF(TRIM(ofc),'') IS NOT NULL GROUP BY ofc QUALIFY ROW_NUMBER() OVER (ORDER BY COUNT(DISTINCT u) DESC)<=25),
ue AS (SELECT u, COUNT(DISTINCT rn) names FROM g WHERE g_rn=0 AND g_of=1 GROUP BY u),
s AS (SELECT 'uei_summary' k, NULL v, COUNT(*) n, SUM(IFF(names>1,1,0)) amt, SUM(IFF(u IS NULL,1,0)) ueis, NULL x FROM ue),
nu AS (SELECT 'null_uei' k, NULL v, SUM(n) n, SUM(amt) amt, NULL, NULL FROM g WHERE g_rn=1 AND g_of=1 AND u IS NULL)
SELECT * FROM rn UNION ALL SELECT * FROM ofc UNION ALL SELECT * FROM s UNION ALL SELECT * FROM nu;

